#!/data/data/com.termux/files/usr/bin/bash
# AGNES (MINEMIND-DEEP) installer for Termux.
# Creates ~/MINEMIND-DEEP from an embedded base64 payload.
set -e
DIR="$HOME/MINEMIND-DEEP"
rm -rf "$DIR"
cd "$HOME"
cat > /tmp/agnes.b64 <<'B64EOF'

B64EOF
base64 -d /tmp/agnes.b64 > /tmp/agnes.tgz
tar xzf /tmp/agnes.tgz -C "$HOME"
rm -f /tmp/agnes.b64 /tmp/agnes.tgz
cd "$DIR"
echo ""
echo "Project installed to $DIR"
echo "Next:  nano .env    (add GEMINI_API_KEY)"
echo "Then:  npm install"
echo "Then:  npm run doctor"
